insert into public.news (slug, published_at, source, title, summary, external_url, image_url) values
('shell-eco-marathon-pologne', '2026-06-29', 'linkedin',
  '{"fr":"Shell Eco-marathon : FabriCS brille en Pologne pour sa première participation en partenariat avec Maxi Mômes !","en":"Shell Eco-marathon: FabriCS shines in Poland on its first participation, in partnership with Maxi Mômes!","pt":"Shell Eco-marathon: a FabriCS brilha na Polônia em sua primeira participação, em parceria com a Maxi Mômes!"}',
  '{"fr":"Premiers essais d''assemblage du châssis avec les entreprises techniques partenaires du Technopôle. Trois semaines avant le banc d''essai.","en":"First chassis assembly trials with the Technopôle''s partner engineering firms. Three weeks before the test bench.","pt":"Primeiros testes de montagem do chassi com as empresas técnicas parceiras do Technopôle. Três semanas antes da bancada de testes."}',
  'https://www.linkedin.com/posts/fabricsmetz_shellecomarathon-fabrics-centralesupaezlec-activity-7477421957974687745-xpjT',
  '/img/cshell-bg.jpg'),
('partenariat-john-cockerill', '2026-06-15', 'fabrics',
  '{"fr":"Partenariat avec John Cockerill : le projet CShell passe à la vitesse supérieure","en":"Partnership with John Cockerill: the CShell project shifts up a gear","pt":"Parceria com a John Cockerill: o projeto CShell acelera"}',
  '{"fr":"Grâce au soutien de John Cockerill, nous reprenons un prototype électrique d’élite pour briller aux Eco-Shell Marathons (Europe & Afrique) et sensibiliser les écoliers messins à l’écomobilité.","en":"With John Cockerill''s support, we are taking over an elite electric prototype to compete in the Shell Eco-marathons (Europe & Africa) and raise eco-mobility awareness among Metz schoolchildren.","pt":"Com o apoio da John Cockerill, assumimos um protótipo elétrico de elite para competir nas Shell Eco-marathons (Europa e África) e sensibilizar as crianças de Metz para a ecomobilidade."}',
  null, '/img/john-cockerill.jpg'),
('maquettes-entreeleves', '2026-04-23', 'press',
  '{"fr":"Des maquettes au tableau : FabriCS soutient la transmission scientifique avec CentraleSupélec","en":"From models to the blackboard: FabriCS supports science outreach with CentraleSupélec","pt":"Das maquetes ao quadro: a FabriCS apoia a divulgação científica com a CentraleSupélec"}',
  '{"fr":"Le Parisien Étudiant met en lumière le projet « EntreÉlèves » de CentraleSupélec Metz, soutenu en coulisses par FabriCS, qui a assisté les étudiants dans la fabrication de leurs maquettes pédagogiques pour les écoliers.","en":"Le Parisien Étudiant features CentraleSupélec Metz''s “EntreÉlèves” project, supported behind the scenes by FabriCS, which helped the students build their teaching models for schoolchildren.","pt":"O Le Parisien Étudiant destaca o projeto “EntreÉlèves” da CentraleSupélec Metz, apoiado nos bastidores pela FabriCS, que ajudou os estudantes a fabricar suas maquetes pedagógicas para crianças."}',
  'https://www.leparisien.fr/etudiant/etudes/ecoles/en-arrivant-aucun-nous-a-parle-dingenieur-ou-de-chercheur-des-etudiants-de-centralesupelec-enseignent-la-science-a-des-ecoliers-QD2GDCHFBJEALN7WDJTHT47YMA.php',
  '/img/eleves.jpg');

insert into public.projects (slug, title, tagline, summary, image_url, is_featured, pillars, objectives) values
('cshell',
  '{"fr":"CShell","en":"CShell","pt":"CShell"}',
  '{"fr":"Le prototype automobile d''éco-mobilité.","en":"The eco-mobility car prototype.","pt":"O protótipo automotivo de ecomobilidade."}',
  '{"fr":"Ce prototype automobile électrique d''éco-mobilité de pointe, acquis par FabriCS, est optimisé par les étudiants en collaboration avec des organismes locaux. Il est destiné à briller lors d''événements internationaux et à sensibiliser le public à l''éco-mobilité.","en":"This cutting-edge electric eco-mobility prototype, acquired by FabriCS, is optimised by students together with local organisations. It is built to shine at international events and to raise public awareness of eco-mobility.","pt":"Este protótipo elétrico de ecomobilidade de ponta, adquirido pela FabriCS, é otimizado pelos estudantes em colaboração com organizações locais. Ele foi feito para brilhar em eventos internacionais e conscientizar o público sobre a ecomobilidade."}',
  '/img/prototype.jpg', true,
  '[
    {"icon":"flag-checkered","title":{"fr":"Compétition","en":"Competition","pt":"Competição"},"text":{"fr":"Un projet d''ingénierie consacré à l''éco-mobilité, avec l''ambition de participer durablement à des compétitions nationales et internationales.","en":"An engineering project dedicated to eco-mobility, aiming to compete for the long term in national and international competitions.","pt":"Um projeto de engenharia dedicado à ecomobilidade, com a ambição de participar de forma duradoura em competições nacionais e internacionais."}},
    {"icon":"microchip","title":{"fr":"Innovation","en":"Innovation","pt":"Inovação"},"text":{"fr":"Électronique, propulsion électrique, informatique embarquée, mécanique et modélisation : un terrain d''application concret pour la mobilité de demain.","en":"Electronics, electric propulsion, embedded software, mechanics and modelling: a real testbed for tomorrow''s mobility.","pt":"Eletrônica, propulsão elétrica, software embarcado, mecânica e modelagem: um campo de aplicação concreto para a mobilidade do futuro."}},
    {"icon":"people-group","title":{"fr":"Transmission","en":"Outreach","pt":"Transmissão"},"text":{"fr":"Apprentissage par la pratique, collaboration entre étudiants, entreprises et acteurs du territoire, et sensibilisation des jeunes aux sciences.","en":"Learning by doing, collaboration between students, companies and local players, and getting young people excited about science.","pt":"Aprendizado prático, colaboração entre estudantes, empresas e atores locais, e sensibilização dos jovens para a ciência."}}
  ]',
  '[
    {"title":{"fr":"Former et inspirer les talents de demain","en":"Train and inspire tomorrow''s talent","pt":"Formar e inspirar os talentos de amanhã"},"text":{"fr":"Développer des compétences techniques sur des projets concrets et susciter des vocations scientifiques auprès des écoliers messins.","en":"Build technical skills on real projects and spark scientific vocations among Metz schoolchildren.","pt":"Desenvolver competências técnicas em projetos concretos e despertar vocações científicas nas crianças de Metz."}},
    {"title":{"fr":"Accélérer l''innovation par la collaboration","en":"Speed up innovation through collaboration","pt":"Acelerar a inovação pela colaboração"},"text":{"fr":"Un écosystème où étudiants, entreprises, laboratoires, associations et collectivités collaborent autour de projets ambitieux.","en":"An ecosystem where students, companies, labs, associations and local authorities work together on ambitious projects.","pt":"Um ecossistema onde estudantes, empresas, laboratórios, associações e governos locais colaboram em projetos ambiciosos."}},
    {"title":{"fr":"Promouvoir une ingénierie durable","en":"Promote sustainable engineering","pt":"Promover uma engenharia sustentável"},"text":{"fr":"Concevoir et expérimenter des solutions favorisant la transition énergétique et l''éco-mobilité.","en":"Design and test solutions that support the energy transition and eco-mobility.","pt":"Projetar e testar soluções que favoreçam a transição energética e a ecomobilidade."}},
    {"title":{"fr":"Faire rayonner notre territoire à l''international","en":"Put our region on the international map","pt":"Projetar nossa região internacionalmente"},"text":{"fr":"Porter des projets d''excellence dans des compétitions internationales pour valoriser les étudiants, nos partenaires et le territoire messin.","en":"Bring projects of excellence to international competitions to showcase our students, partners and the Metz region.","pt":"Levar projetos de excelência a competições internacionais para valorizar os estudantes, nossos parceiros e a região de Metz."}}
  ]');

